(function(){var wrapper=document.getElementById('trips-wrapper');var template=document.getElementById('trip-template');var addBtn=document.getElementById('add-trip');if(!wrapper||!template||!addBtn){return;}var tripsNode=document.getElementById('transport-movement-trips-json');var trips=[];try{trips=JSON.parse(tripsNode?tripsNode.textContent:'[]')||[];}catch(error){trips=[];}var reindexTrips=function(){wrapper.querySelectorAll('.trip-item').forEach(function(item,index){item.querySelectorAll('[data-name]').forEach(function(field){var key=field.getAttribute('data-name');field.name='trips['+index+']['+key+']';});});};var addTripRow=function(trip){trip=trip||{};var node=template.content.cloneNode(true);var item=node.querySelector('.trip-item');item.querySelectorAll('[data-name]').forEach(function(field){var key=field.getAttribute('data-name');if(trip[key]!==undefined&&trip[key]!==null){field.value=trip[key];}});item.querySelector('.remove-trip').addEventListener('click',function(){item.remove();if(!wrapper.querySelector('.trip-item')){addTripRow();return;}reindexTrips();});wrapper.appendChild(node);reindexTrips();};addBtn.addEventListener('click',function(){addTripRow();});var normalizedTrips=Array.isArray(trips)?trips:Object.values(trips||{});if(normalizedTrips.length){normalizedTrips.forEach(function(trip){addTripRow(trip);});}else{addTripRow();}})();